button:focus-visible, a:focus-visible, input:focus-visible {
  outline: 3px solid #163f70;
  outline-offset: 3px;
}

/* The value must account for the actual height of the sticky area. */
html { scroll-padding-block-start: 7rem; }
[id], input, button, a { scroll-margin-block: 1rem; }

.request { inline-size: min(100%, 56rem); }
.request input { max-inline-size: 100%; box-sizing: border-box; }
.request label, .request p { overflow-wrap: anywhere; }
.request-row { display: flex; flex-wrap: wrap; gap: 1rem; }

.day-button {
  min-inline-size: 2.75rem;
  min-block-size: 2.75rem;
  padding: .5rem;
}

.opened { animation: panel-flight .25s; }
@media (prefers-reduced-motion: reduce) {
  .opened { animation: none; }
  html { scroll-behavior: auto; }
}
